# the unmodified project must pass first, or "caught" would mean nothing
env0 = dict(os.environ, NODE_PATH=NODE_PATH)
for t0 in PY:
    r0 = subprocess.run(PY[t0], cwd=ROOT, capture_output=True, text=True, env=env0, timeout=300)
    if r0.returncode != 0:
        print("BASELINE FAILS (%s), rebuild first:" % t0, r0.stdout[-300:], r0.stderr[-300:]); sys.exit(3)
killed = 0
for entry in M:
    name, path, a, b, tests = entry[:5]
    want = entry[5] if len(entry) > 5 else 1
    src = open(path, encoding="utf-8", newline="").read()
    if src.count(a) != want:
        print("BROKEN MUTANT (pattern count %d):" % src.count(a), name); sys.exit(2)
    open(path, "w", encoding="utf-8", newline="").write(src.replace(a, b))
    try:
        rcs = []
        for t in tests:
            env = dict(os.environ, NODE_PATH=NODE_PATH)
            rcs.append(subprocess.run(PY[t], cwd=ROOT, capture_output=True, text=True, env=env, timeout=300).returncode)
    finally:
        open(path, "w", encoding="utf-8", newline="").write(src)
    dead = any(rc != 0 for rc in rcs)
    killed += dead
    print("caught  " if dead else "SURVIVED", name)
print("%d of %d mutants caught" % (killed, len(M)))
sys.exit(0 if killed == len(M) else 1)
